import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.LX5S0jbT.js";const q=JSON.parse('{"title":"设置参考","description":"","frontmatter":{},"headers":[],"relativePath":"zh/settings.md","filePath":"zh/settings.md"}'),a={name:"zh/settings.md"};function r(l,t,n,i,s,u){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="设置参考" tabindex="-1">设置参考 <a class="header-anchor" href="#设置参考" aria-label="Permalink to &quot;设置参考&quot;">​</a></h1><p>本参考列出用户可配置的设置项及其类型、默认值和用途。项目设置覆盖 agent 目录设置。资源列表会合并。文件位置和信任行为见<a href="./configuration.html">配置</a>。</p><p>在 <code>settings.json</code> 中添加 <code>&quot;$schema&quot;: &quot;https://pi.dev/schemas/settings.schema.json&quot;</code> 可获得编辑器校验和补全。</p><p><a id="model-and-thinking"></a></p><h2 id="模型与思考" tabindex="-1">模型与思考 <a class="header-anchor" href="#模型与思考" aria-label="Permalink to &quot;模型与思考&quot;">​</a></h2><p><a id="model-cycling"></a></p><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>defaultProvider</code></td><td>string</td><td>自动</td><td>启动时的 AI 提供商（provider）。</td></tr><tr><td><code>defaultModel</code></td><td>string</td><td>自动</td><td>启动时的模型 ID。</td></tr><tr><td><code>defaultThinkingLevel</code></td><td><code>&quot;off&quot; | &quot;minimal&quot; | &quot;low&quot; | &quot;medium&quot; | &quot;high&quot; | &quot;xhigh&quot; | &quot;max&quot;</code></td><td><code>&quot;medium&quot;</code></td><td>启动时的思考级别（thinking level）。</td></tr><tr><td><code>modelThinkingLevels</code></td><td>object</td><td>无</td><td>按精确的 <code>provider/modelId</code> 设置各模型的启动思考级别。</td></tr><tr><td><code>thinkingBudgets</code></td><td>object</td><td>内置预算</td><td><code>minimal</code>、<code>low</code>、<code>medium</code> 和 <code>high</code> 思考级别的 token 预算。</td></tr><tr><td><code>enabledModels</code></td><td><code>string[]</code></td><td>所有可用模型</td><td>用于启动选择和模型循环切换的模型模式。格式与 <code>--models</code> 相同。</td></tr><tr><td><code>hideThinkingBlock</code></td><td>boolean</td><td><code>false</code></td><td>在对话记录中隐藏思考块。</td></tr><tr><td><code>showCacheMissNotices</code></td><td>boolean</td><td><code>false</code></td><td>显示显著缓存未命中、缓存预热成功、压缩用量和提供商恢复的通知。</td></tr><tr><td><code>cacheWarming</code></td><td><code>&quot;off&quot; | &quot;streaming&quot; | &quot;idle&quot;</code></td><td><code>&quot;streaming&quot;</code></td><td>在活跃运行期间（<code>&quot;idle&quot;</code> 则在运行之间）保持符合条件的提供商提示词缓存处于预热状态。仅限全局设置。</td></tr></tbody></table><p>缓存预热仅在模型声明了缓存生存期，且 Pi 估计可避免的缓存未命中成本不低于 $0.05 时运行。预热用量计入会话总额，但不进入模型上下文。<code>/session</code> 显示下一次决策；扩展可以通过 <code>cache_warming_decision</code> 覆盖它。见<a href="./models.html#prompt-cache-lifetimes">提示词缓存生存期</a>。</p><p>模型选择和思考控制见<a href="./models.html">选择模型</a>。</p><h2 id="交互" tabindex="-1">交互 <a class="header-anchor" href="#交互" aria-label="Permalink to &quot;交互&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>steeringMode</code></td><td><code>&quot;all&quot; | &quot;one-at-a-time&quot;</code></td><td><code>&quot;one-at-a-time&quot;</code></td><td>排队引导消息（steering messages）的送达方式。</td></tr><tr><td><code>followUpMode</code></td><td><code>&quot;all&quot; | &quot;one-at-a-time&quot;</code></td><td><code>&quot;one-at-a-time&quot;</code></td><td>排队后续消息（follow-up messages）的送达方式。</td></tr><tr><td><code>externalEditor</code></td><td>string</td><td><code>$VISUAL</code>、<code>$EDITOR</code>，然后是平台默认</td><td>外部编辑器快捷键打开的命令。</td></tr><tr><td><code>doubleEscapeAction</code></td><td><code>&quot;tree&quot; | &quot;fork&quot; | &quot;none&quot;</code></td><td><code>&quot;tree&quot;</code></td><td>空编辑器下双击 Escape 的动作。</td></tr><tr><td><code>treeFilterMode</code></td><td><code>&quot;default&quot; | &quot;no-tools&quot; | &quot;user-only&quot; | &quot;labeled-only&quot; | &quot;all&quot;</code></td><td><code>&quot;default&quot;</code></td><td><code>/tree</code> 使用的初始过滤器。</td></tr><tr><td><code>defaultProjectTrust</code></td><td><code>&quot;ask&quot; | &quot;always&quot; | &quot;never&quot;</code></td><td><code>&quot;ask&quot;</code></td><td>备选的项目信任行为。<strong>只能在 agent 目录设置中配置。</strong></td></tr></tbody></table><p><a id="tools"></a></p><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>defaultTools</code></td><td><code>string[]</code></td><td><code>read</code>, <code>bash</code>, <code>edit</code>, <code>write</code></td><td>启动时启用的工具。普通名称替换默认值；<code>+name</code> 添加工具，<code>-name</code> 移除工具。空数组禁用所有内置工具，但不影响扩展或 SDK 工具。</td></tr><tr><td><code>codemode.mode</code></td><td><code>&quot;on&quot;</code> | <code>&quot;only&quot;</code></td><td><code>&quot;on&quot;</code></td><td><code>codemode</code> 工具激活时展示工具的方式。<code>on</code>：在已声明工具的描述后附加从脚本调用的说明，<code>codemode</code> 只列出未声明的工具。<code>only</code>：<code>codemode</code> 列出脚本可调用的所有工具，活跃的内置和扩展工具对模型隐藏，模型需通过 <code>codemode</code> 访问它们。</td></tr><tr><td><code>codemode.inlineBudget</code></td><td>number</td><td><code>3000</code></td><td><code>codemode</code> 工具描述中可用于工具声明的预估 token 数（字符数 / 4）。放不下的工具会被略过，可通过 <code>searchTools()</code> 查找。<code>0</code> 只列出命名空间。</td></tr></tbody></table><p>可用的内置工具有 <code>read</code>、<code>bash</code>、<code>powershell</code>、<code>edit</code>、<code>write</code>、<code>grep</code>、<code>find</code> 和 <code>ls</code>。<code>defaultTools</code> 还可以指定 <code>codemode</code> 和 <code>tool_search</code>（由内置扩展注册为未激活），以及其他注册为未激活的扩展工具。</p><p>只包含 <code>+name</code> 和 <code>-name</code> 的列表会修改继承的选择而不是替换它。例如，以下配置在默认工具之外启用 <code>codemode</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;defaultTools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;+codemode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这会用 <code>powershell</code> 替换 <code>bash</code> 并启用 <code>grep</code>：<code>[&quot;-bash&quot;, &quot;+powershell&quot;, &quot;+grep&quot;]</code>。项目设置叠加在用户设置之上：只含 <code>+name</code> 和 <code>-name</code> 的项目列表修改用户的选择，含普通名称的项目列表则替换它。在同一个列表中，普通名称构成选择，<code>+name</code> 和 <code>-name</code> 随后按顺序生效。</p><p><code>/reload</code> 会启用新加入 <code>defaultTools</code> 的工具，但不会禁用从中移除的工具，也不会重新启用你已关闭的未变动工具。带普通名称的 <code>--tools</code>、<code>--no-tools</code> 和 <code>--no-builtin-tools</code> 会覆盖 <code>defaultTools</code>，<code>/reload</code> 时也是如此。</p><p>CLI 工具选项只在单次调用中覆盖此设置。只含 <code>+name</code> 和 <code>-name</code> 的 <code>--tools</code> 会改为修改已解析的 <code>defaultTools</code> 选择，例如 <code>pi --tools +codemode</code>。<code>/reload</code> 时这些条目同样作用于重新加载后的设置，因此用 <code>-name</code> 移除的工具保持移除。见<a href="./cli.html#tools">命令行</a>。</p><p><a id="sessions-and-context"></a></p><h2 id="会话与上下文" tabindex="-1">会话与上下文 <a class="header-anchor" href="#会话与上下文" aria-label="Permalink to &quot;会话与上下文&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>sessionDir</code></td><td>string</td><td>agent 会话目录</td><td>会话存储目录。相对路径基于工作目录解析。<code>PI_CODING_AGENT_SESSION_DIR</code> 和 <code>--session-dir</code> 覆盖此设置。</td></tr><tr><td><code>sessionShareDestination</code></td><td><code>&quot;auto&quot; | &quot;gist&quot; | &quot;radius&quot;</code></td><td><code>&quot;auto&quot;</code></td><td><code>/share</code> 使用的目的地。<code>auto</code> 在已认证时使用 Radius，否则创建 GitHub gist。<code>gist</code> 始终使用 gist。<code>radius</code> 要求 Radius 认证，且不会回退到 gist。</td></tr></tbody></table><p><a id="compaction"></a></p><h3 id="压缩-compaction" tabindex="-1">压缩（compaction） <a class="header-anchor" href="#压缩-compaction" aria-label="Permalink to &quot;压缩（compaction）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>compaction.enabled</code></td><td>boolean</td><td><code>true</code></td><td>启用自动压缩。</td></tr><tr><td><code>compaction.reserveTokens</code></td><td>number</td><td><code>16384</code></td><td>空闲上下文 token 低于该值时启动自动压缩。</td></tr><tr><td><code>compaction.keepRecentTokens</code></td><td>number</td><td><code>20000</code></td><td>不参与摘要、予以保留的近期 token 数。</td></tr><tr><td><code>compaction.modelOverrides</code></td><td>object</td><td>无</td><td>按精确的 <code>provider/modelId</code> 设置各模型的 token 配置。</td></tr></tbody></table><p><a id="per-model-compaction-overrides"></a></p><p>压缩 token 值必须是非负安全整数。每个值依次从匹配的模型覆盖、普通压缩设置、内置默认值中独立解析。项目和用户对象在模型查找之前先合并。</p><p>触发、摘要和校验行为见<a href="./compaction.html">压缩参考</a>。</p><h3 id="分支摘要" tabindex="-1">分支摘要 <a class="header-anchor" href="#分支摘要" aria-label="Permalink to &quot;分支摘要&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>branchSummary.reserveTokens</code></td><td>number</td><td><code>16384</code></td><td>对分支历史做摘要时保留的 token 数。</td></tr><tr><td><code>branchSummary.skipPrompt</code></td><td>boolean</td><td><code>false</code></td><td>跳过分支摘要提示，默认不做摘要。</td></tr></tbody></table><p><a id="terminal-and-display"></a></p><h2 id="终端与显示" tabindex="-1">终端与显示 <a class="header-anchor" href="#终端与显示" aria-label="Permalink to &quot;终端与显示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>theme</code></td><td>string</td><td><code>&quot;system&quot;</code></td><td>内置或自定义主题名。<code>system</code> 从终端主题取色。</td></tr><tr><td><code>quietStartup</code></td><td>boolean | <code>&quot;header&quot;</code></td><td><code>false</code></td><td><code>true</code> 隐藏启动横幅和已加载资源列表。<code>&quot;header&quot;</code> 保留横幅（版本和按键提示），但隐藏模型范围行和已加载资源列表。</td></tr><tr><td><code>tuiMode</code></td><td><code>&quot;regular&quot; | &quot;fullscreen&quot;</code></td><td><code>&quot;fullscreen&quot;</code></td><td>交互式终端 UI 模式。</td></tr><tr><td><code>fullscreenExitOutput</code></td><td><code>&quot;transcript&quot; | &quot;resume-hint&quot;</code></td><td><code>&quot;transcript&quot;</code></td><td>全屏模式退出时打印的输出。</td></tr><tr><td><code>fullscreenScrollbar</code></td><td><code>&quot;auto&quot; | &quot;always&quot; | &quot;hidden&quot;</code></td><td><code>&quot;auto&quot;</code></td><td>全屏对话记录滚动条行为。</td></tr><tr><td><code>fullscreenCopyOnSelect</code></td><td>boolean</td><td><code>true</code></td><td>在全屏模式下自动复制选中的文本。</td></tr><tr><td><code>fullscreenWheelScrollLines</code></td><td><code>&quot;auto&quot;</code> | number</td><td><code>&quot;auto&quot;</code></td><td>全屏模式下每个鼠标滚轮事件滚动的行数，取值 1 到 100。<code>&quot;auto&quot;</code> 在本地 macOS 终端中每个事件滚动一行（它们已对滚轮和触控板输入加速）；在其他环境以及通过 SSH 时，快速滚动最多加速到每个事件 6 行。Alt+滚轮滚动距离为五倍。</td></tr><tr><td><code>editorPaddingX</code></td><td>number</td><td><code>0</code></td><td>编辑器的水平内边距，0 到 3 格。</td></tr><tr><td><code>outputPad</code></td><td><code>0 | 1</code></td><td><code>1</code></td><td>消息、工具输出、<code>!</code> 命令输出和摘要块的水平留白。</td></tr><tr><td><code>autocompleteMaxVisible</code></td><td>number</td><td><code>5</code></td><td>可见的自动补全条目数，3 到 20。</td></tr><tr><td><code>showHardwareCursor</code></td><td>boolean</td><td><code>false</code></td><td>使用终端光标而非 Pi 绘制的光标。Pi 仍会为输入法定位光标。</td></tr><tr><td><code>terminal.showImages</code></td><td>boolean</td><td><code>true</code></td><td>在支持时显示内联图片。</td></tr><tr><td><code>terminal.imageWidthCells</code></td><td>number</td><td><code>60</code></td><td>内联图片的首选宽度（终端格数）。</td></tr><tr><td><code>terminal.clearOnShrink</code></td><td>boolean</td><td><code>false</code></td><td>渲染内容缩小时清除空行。未设置时，<code>PI_CLEAR_ON_SHRINK=1</code> 可启用。</td></tr><tr><td><code>terminal.showTerminalProgress</code></td><td>boolean</td><td><code>false</code></td><td>在终端标签页显示 OSC 9;4 进度。</td></tr><tr><td><code>terminal.hyperlinks</code></td><td><code>boolean | &quot;auto&quot;</code></td><td><code>&quot;auto&quot;</code></td><td>覆盖 OSC 8 超链接检测。</td></tr><tr><td><code>terminal.images</code></td><td><code>&quot;kitty&quot; | &quot;iterm2&quot; | &quot;auto&quot; | false</code></td><td><code>&quot;auto&quot;</code></td><td>覆盖内联图片协议检测。</td></tr><tr><td><code>terminal.trueColor</code></td><td><code>boolean | &quot;auto&quot;</code></td><td><code>&quot;auto&quot;</code></td><td>覆盖真彩色检测。</td></tr><tr><td><code>images.autoResize</code></td><td>boolean</td><td><code>true</code></td><td>发送给模型前将图片缩放到不超过 2000 x 2000 像素。</td></tr><tr><td><code>images.blockImages</code></td><td>boolean</td><td><code>false</code></td><td>禁止向模型发送图片。</td></tr><tr><td><code>markdown.codeBlockIndent</code></td><td>string</td><td><code>&quot; &quot;</code></td><td>渲染代码块的缩进前缀。</td></tr><tr><td><code>markdown.mermaid</code></td><td><code>&quot;off&quot; | &quot;final&quot; | &quot;streaming&quot;</code></td><td><code>&quot;streaming&quot;</code></td><td>Mermaid 渲染模式。</td></tr></tbody></table><p>格式和平台细节见<a href="./themes.html">主题</a>和<a href="./terminal-setup.html">终端设置</a>。</p><h2 id="网络与重试" tabindex="-1">网络与重试 <a class="header-anchor" href="#网络与重试" aria-label="Permalink to &quot;网络与重试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>transport</code></td><td><code>&quot;auto&quot; | &quot;sse&quot; | &quot;websocket&quot; | &quot;websocket-cached&quot;</code></td><td><code>&quot;auto&quot;</code></td><td>支持多种传输方式的 AI 提供商的首选传输方式。</td></tr><tr><td><code>httpProxy</code></td><td>string</td><td>无</td><td>作为 <code>HTTP_PROXY</code> 和 <code>HTTPS_PROXY</code> 应用于 Pi 管理的 HTTP 客户端的代理 URL。<strong>只能在 agent 目录设置中配置。</strong></td></tr><tr><td><code>httpIdleTimeoutMs</code></td><td>number | <code>&quot;disabled&quot;</code></td><td><code>300000</code></td><td>HTTP 头和主体的空闲超时（毫秒）。设为 <code>0</code> 或 <code>&quot;disabled&quot;</code> 可禁用。</td></tr><tr><td><code>websocketConnectTimeoutMs</code></td><td>number | <code>&quot;disabled&quot;</code></td><td><code>15000</code></td><td>WebSocket 连接超时（毫秒）。设为 <code>0</code> 或 <code>&quot;disabled&quot;</code> 可禁用。</td></tr><tr><td><code>retry.enabled</code></td><td>boolean</td><td><code>true</code></td><td>启用 agent 级自动重试以应对瞬时故障。</td></tr><tr><td><code>retry.maxRetries</code></td><td>number</td><td><code>3</code></td><td>agent 级最大重试次数。</td></tr><tr><td><code>retry.baseDelayMs</code></td><td>number</td><td><code>2000</code></td><td>指数退避的初始延迟（毫秒）。</td></tr><tr><td><code>retry.maxAgentDelayMs</code></td><td>number</td><td><code>60000</code></td><td>agent 级最大重试延迟（毫秒）。</td></tr><tr><td><code>retry.provider.timeoutMs</code></td><td>number</td><td><code>httpIdleTimeoutMs</code></td><td>提供商请求超时（毫秒）。</td></tr><tr><td><code>retry.provider.maxRetries</code></td><td>number</td><td><code>0</code></td><td>提供商级重试次数。</td></tr><tr><td><code>retry.provider.maxRetryDelayMs</code></td><td>number</td><td><code>60000</code></td><td>服务器请求的最大延迟（毫秒）。设为 <code>0</code> 可禁用该限制。</td></tr></tbody></table><p>除非需要提供商级重试，否则请保持 <code>retry.provider.maxRetries</code> 为 <code>0</code>。提供商重试可能延误 Pi 自行处理配额和用量限制错误。</p><p><a id="shell"></a></p><h2 id="shell" tabindex="-1">Shell <a class="header-anchor" href="#shell" aria-label="Permalink to &quot;Shell&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>shellPath</code></td><td>string</td><td>平台默认</td><td>自定义 shell 可执行文件路径。支持开头的 <code>~</code>。</td></tr><tr><td><code>shellCommandPrefix</code></td><td>string</td><td>无</td><td>前置到每条 shell 命令的前缀。</td></tr><tr><td><code>npmCommand</code></td><td><code>string[]</code></td><td><code>npm</code></td><td>用于 npm 包查询和安装的命令及参数。</td></tr></tbody></table><p>Shell 配置见 <a href="./shell-aliases.html">Shell 别名</a>，包管理行为见 <a href="./packages.html">Pi 包</a>。</p><p><a id="resources"></a></p><h2 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to &quot;资源&quot;">​</a></h2><p>用户设置中的资源路径基于 agent 目录解析。项目设置中的路径基于项目 <code>.pi</code> 目录解析。支持绝对路径和 <code>~</code>。</p><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>packages</code></td><td>array</td><td><code>[]</code></td><td>npm、git 或本地 Pi 包来源。见 <a href="./packages.html">Pi 包</a>。</td></tr><tr><td><code>extensions</code></td><td><code>string[]</code></td><td><code>[]</code></td><td>扩展（extension）文件或目录。</td></tr><tr><td><code>skills</code></td><td><code>string[]</code></td><td><code>[]</code></td><td>技能（skill）文件或目录。</td></tr><tr><td><code>prompts</code></td><td><code>string[]</code></td><td><code>[]</code></td><td>提示词模板（prompt template）文件或目录。</td></tr><tr><td><code>themes</code></td><td><code>string[]</code></td><td><code>[]</code></td><td>主题文件或目录。</td></tr><tr><td><code>enableSkillCommands</code></td><td>boolean</td><td><code>true</code></td><td>将技能注册为 <code>/skill:name</code> 命令。</td></tr></tbody></table><p>资源数组支持用 <code>!pattern</code> 排除 glob、用 <code>+path</code> 精确包含、用 <code>-path</code> 精确排除。用户级和项目设置中列出的资源 Pi 都会加载。</p><p>内置扩展在 <code>extensions</code> 中名为 <code>builtin:mcp</code>、<code>builtin:llama.cpp</code>、<code>builtin:codemode</code> 和 <code>builtin:tool-search</code>。它们默认加载；<code>-builtin:mcp</code> 可禁用其中一个。项目设置中的 <code>+builtin:&lt;name&gt;</code> 或 <code>-builtin:&lt;name&gt;</code> 条目覆盖用户设置。<code>pi config</code> 会在 Built-in 下列出它们。<code>--no-extensions</code> 也会禁用它们，<code>-e builtin:&lt;name&gt;</code> 可显式加载一个。</p><h2 id="更新、遥测与警告" tabindex="-1">更新、遥测与警告 <a class="header-anchor" href="#更新、遥测与警告" aria-label="Permalink to &quot;更新、遥测与警告&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>collapseChangelog</code></td><td>boolean</td><td><code>false</code></td><td>更新后显示精简的更新日志。</td></tr><tr><td><code>enableInstallTelemetry</code></td><td>boolean</td><td><code>true</code></td><td>启用匿名的安装/更新上报和所选提供商的归因头。不控制更新检查。</td></tr><tr><td><code>enableAnalytics</code></td><td>boolean</td><td><code>false</code></td><td>同意共享分析数据。目前仅由实验性的首次运行设置使用。</td></tr><tr><td><code>warnings.anthropicExtraUsage</code></td><td>boolean</td><td><code>true</code></td><td>当 Anthropic 订阅认证可能使用付费额外用量时发出警告。</td></tr></tbody></table>`,50)])])}const m=d(a,[["render",r]]);export{q as __pageData,m as default};
